beforeSaveCustomScript:
if (websiteReferenceId != null && websiteReferenceId != '') {
    $contact = ifThenElse(
        websiteContactName != null && websiteContactName != '',
        websiteContactName,
        ifThenElse(parentName != null && parentName != '', parentName, 'Segnalazione')
    );
    $sportello = ifThenElse(
        sportelloDisplayName != null && sportelloDisplayName != '',
        sportelloDisplayName,
        ifThenElse(
            type == 'SportelloDigitale',
            'Sportello digitale',
            ifThenElse(
                type == 'SportelloLegale',
                'Sportello legale',
                ifThenElse(
                    type == 'RichiestaGenerica',
                    'Richiesta generica',
                    ifThenElse(
                        type == 'AssistanceRequest',
                        'Richiesta di assistenza',
                        ifThenElse(type != null && type != '', type, 'Altro')
                    )
                )
            )
        )
    );
    $dateLabel = ifThenElse(createdAt != null && createdAt != '', datetime\format(createdAt, 'Europe/Rome', 'DD/MM/YYYY'), datetime\format(datetime\now(), 'Europe/Rome', 'DD/MM/YYYY'));
    name = string\concatenate($contact, ' | ', $dateLabel, ' | ', $sportello);
}
